const https = require('https');

const serviceRole =
  $env.P6C_SUPABASE_SERVICE_ROLE_KEY;

if (
  typeof serviceRole !== 'string' ||
  serviceRole.length < 20
) {
  throw new Error(
    'P6C_SUPABASE_SERVICE_ROLE_KEY is unavailable'
  );
}

const body = JSON.stringify({
  p_worker_id:
    'n8n-phase6c-recovery-sms-worker',

  p_event_types: [
    'TWILIO_MISSED_CALL_RECOVERY_READY',
  ],

  p_limit: 10,

  p_lock_timeout_seconds: 300,
});

const response = await new Promise(
  (resolve, reject) => {
    const req = https.request(
      {
        hostname:
          'lirmmoebcvmoixxfbmlu.supabase.co',

        port: 443,

        path:
          '/rest/v1/rpc/claim_outbox_events_v1',

        method: 'POST',

        headers: {
          apikey: serviceRole,

          Authorization:
            `Bearer ${serviceRole}`,

          'Content-Type':
            'application/json',
        },

        timeout: 15000,
      },

      (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          resolve({
            status: res.statusCode,
            body: data,
          });
        });
      }
    );

    req.on('timeout', () => {
      req.destroy(
        new Error('SUPABASE_CLAIM_TIMEOUT')
      );
    });

    req.on('error', reject);

    req.write(body);
    req.end();
  }
);

if (
  response.status < 200 ||
  response.status >= 300
) {
  throw new Error(
    `SUPABASE_CLAIM_HTTP_${response.status}: ${response.body}`
  );
}

const rows =
  response.body.trim() === ''
    ? []
    : JSON.parse(response.body);

if (!Array.isArray(rows)) {
  throw new Error(
    'SUPABASE_CLAIM_RESPONSE_NOT_ARRAY'
  );
}

return rows.map((row) => ({
  json: row,
}));

const https = require('https');

const workerSecret =
  $env.P6C_RECOVERY_WORKER_SECRET;

if (
  typeof workerSecret !== 'string' ||
  workerSecret.length < 20
) {
  throw new Error(
    'P6C_RECOVERY_WORKER_SECRET is unavailable'
  );
}

const inputItems = $input.all();
const results = [];

for (const item of inputItems) {
  const outboxEventId =
    item.json.outbox_event_id;

  if (
    typeof outboxEventId !== 'string' ||
    outboxEventId.length < 30
  ) {
    throw new Error(
      'Missing or invalid outbox_event_id'
    );
  }

  const requestBody = JSON.stringify({
    outbox_event_id: outboxEventId,
    worker_id:
      'n8n-phase6c-recovery-sms-worker',
  });

  const response = await new Promise(
    (resolve, reject) => {
      const req = https.request(
        {
          hostname:
            'lirmmoebcvmoixxfbmlu.supabase.co',

          port: 443,

          path:
            '/functions/v1/twilio-recovery-sms',

          method: 'POST',

          headers: {
            'x-recovery-worker-secret':
              workerSecret,

            'Content-Type':
              'application/json',
          },

          timeout: 30000,
        },

        (res) => {
          let body = '';

          res.on('data', (chunk) => {
            body += chunk;
          });

          res.on('end', () => {
            resolve({
              status: res.statusCode,
              body,
            });
          });
        }
      );

      req.on('timeout', () => {
        req.destroy(
          new Error(
            'RECOVERY_SMS_REQUEST_TIMEOUT'
          )
        );
      });

      req.on('error', reject);

      req.write(requestBody);
      req.end();
    }
  );

  if (
    response.status < 200 ||
    response.status >= 300
  ) {
    throw new Error(
      `RECOVERY_SMS_HTTP_${response.status}: ` +
      response.body.slice(0, 500)
    );
  }

  let parsed;

  try {
    parsed = JSON.parse(response.body);
  } catch {
    throw new Error(
      'RECOVERY_SMS_INVALID_JSON'
    );
  }

  results.push({
    json: parsed,
  });
}

return results;

const https = require('https');

const serviceRole = $env.P6C_SUPABASE_SERVICE_ROLE_KEY;

if (!serviceRole) {
  throw new Error(
    'P6C_SUPABASE_SERVICE_ROLE_KEY is unavailable'
  );
}

const items = $input.all();
const output = [];

for (const item of items) {
  const outboxEventId = item.json.outbox_event_id;

  if (!outboxEventId) {
    throw new Error(
      'Missing outbox_event_id'
    );
  }

  const body = JSON.stringify({
    p_outbox_event_id: outboxEventId,
    p_worker_id: 'n8n-phase6c-recovery-sms-worker',
  });

  const response = await new Promise(
    (resolve, reject) => {
      const req = https.request(
        {
          hostname: 'lirmmoebcvmoixxfbmlu.supabase.co',
          port: 443,
          path: '/rest/v1/rpc/complete_outbox_event_v1',
          method: 'POST',
          headers: {
            apikey: serviceRole,
            Authorization: `Bearer ${serviceRole}`,
            'Content-Type': 'application/json',
          },
          timeout: 15000,
        },
        (res) => {
          let data = '';

          res.on('data', (chunk) => {
            data += chunk;
          });

          res.on('end', () => {
            resolve({
              status: res.statusCode,
              body: data,
            });
          });
        }
      );

      req.on('timeout', () => {
        req.destroy(
          new Error('SUPABASE_COMPLETE_TIMEOUT')
        );
      });

      req.on('error', reject);

      req.write(body);
      req.end();
    }
  );

  if (
    response.status < 200 ||
    response.status >= 300
  ) {
    throw new Error(
      `SUPABASE_COMPLETE_HTTP_${response.status}: ${response.body}`
    );
  }

  const rows =
    response.body.trim() === ''
      ? []
      : JSON.parse(response.body);

  if (!Array.isArray(rows)) {
    throw new Error(
      'SUPABASE_COMPLETE_RESPONSE_NOT_ARRAY'
    );
  }

  for (const row of rows) {
    output.push({
      json: row,
    });
  }
}

return output;

const https = require('https');

const serviceRole =
  $env.P6C_SUPABASE_SERVICE_ROLE_KEY;

if (
  typeof serviceRole !== 'string' ||
  serviceRole.length < 20
) {
  throw new Error(
    'P6C_SUPABASE_SERVICE_ROLE_KEY is unavailable'
  );
}

const items = $input.all();
const output = [];

for (const item of items) {
  const outboxEventId =
    item.json.outbox_event_id;

  if (!outboxEventId) {
    throw new Error(
      'Missing outbox_event_id'
    );
  }

  const errorCode =
    item.json.reason_code ||
    'RECOVERY_SMS_RETRYABLE_FAILURE';

  const retryAfterSeconds =
    Number.isInteger(
      item.json.retry_after_seconds
    ) &&
    item.json.retry_after_seconds >= 0
      ? item.json.retry_after_seconds
      : 60;

  const body = JSON.stringify({
    p_outbox_event_id:
      outboxEventId,

    p_worker_id:
      'n8n-phase6c-recovery-sms-worker',

    p_error:
      errorCode,

    p_retry_after_seconds:
      retryAfterSeconds,
  });

  const response = await new Promise(
    (resolve, reject) => {
      const req = https.request(
        {
          hostname:
            'lirmmoebcvmoixxfbmlu.supabase.co',

          port: 443,

          path:
            '/rest/v1/rpc/fail_outbox_event_v1',

          method: 'POST',

          headers: {
            apikey: serviceRole,

            Authorization:
              `Bearer ${serviceRole}`,

            'Content-Type':
              'application/json',
          },

          timeout: 15000,
        },

        (res) => {
          let data = '';

          res.on('data', (chunk) => {
            data += chunk;
          });

          res.on('end', () => {
            resolve({
              status: res.statusCode,
              body: data,
            });
          });
        }
      );

      req.on('timeout', () => {
        req.destroy(
          new Error(
            'SUPABASE_FAIL_OUTBOX_TIMEOUT'
          )
        );
      });

      req.on('error', reject);

      req.write(body);
      req.end();
    }
  );

  if (
    response.status < 200 ||
    response.status >= 300
  ) {
    throw new Error(
      `SUPABASE_FAIL_HTTP_${response.status}: ` +
      response.body.slice(0, 500)
    );
  }

  const rows =
    response.body.trim() === ''
      ? []
      : JSON.parse(response.body);

  if (!Array.isArray(rows)) {
    throw new Error(
      'SUPABASE_FAIL_RESPONSE_NOT_ARRAY'
    );
  }

  for (const row of rows) {
    output.push({
      json: row,
    });
  }
}

return output;
